"""A small stack-based virtual machine."""


class VMError(Exception):
    """Base class for all VM errors."""


class StackUnderflow(VMError):
    """Popping/peeking an empty operand stack."""


class BadJump(VMError):
    """Jump/call target out of range or into nowhere."""


class BadOpcode(VMError):
    """Unknown instruction name."""


class StepLimitExceeded(VMError):
    """Executed more than max_steps instructions."""


class VMZeroDivision(VMError):
    """DIV or MOD with zero divisor."""


def run(program: list, max_steps: int = 10_000) -> list:
    stack = []
    store = {}
    call_stack = []
    pc = 0
    steps = 0
    n = len(program)

    def pop():
        if not stack:
            raise StackUnderflow()
        return stack.pop()

    def check_target(target):
        if target < 0 or target > n:
            raise BadJump()

    while pc < n:
        steps += 1
        if steps > max_steps:
            raise StepLimitExceeded()

        instr = program[pc]
        op = instr[0]
        arg = instr[1] if len(instr) > 1 else None

        if op == "PUSH":
            stack.append(arg)
            pc += 1
        elif op == "POP":
            pop()
            pc += 1
        elif op == "DUP":
            if not stack:
                raise StackUnderflow()
            stack.append(stack[-1])
            pc += 1
        elif op == "SWAP":
            if len(stack) < 2:
                raise StackUnderflow()
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
        elif op == "ADD":
            b = pop()
            a = pop()
            stack.append(a + b)
            pc += 1
        elif op == "SUB":
            b = pop()
            a = pop()
            stack.append(a - b)
            pc += 1
        elif op == "MUL":
            b = pop()
            a = pop()
            stack.append(a * b)
            pc += 1
        elif op == "DIV":
            b = pop()
            a = pop()
            if b == 0:
                raise VMZeroDivision()
            stack.append(a // b)
            pc += 1
        elif op == "MOD":
            b = pop()
            a = pop()
            if b == 0:
                raise VMZeroDivision()
            stack.append(a % b)
            pc += 1
        elif op == "NEG":
            a = pop()
            stack.append(-a)
            pc += 1
        elif op == "EQ":
            b = pop()
            a = pop()
            stack.append(1 if a == b else 0)
            pc += 1
        elif op == "LT":
            b = pop()
            a = pop()
            stack.append(1 if a < b else 0)
            pc += 1
        elif op == "GT":
            b = pop()
            a = pop()
            stack.append(1 if a > b else 0)
            pc += 1
        elif op == "LOAD":
            stack.append(store.get(arg, 0))
            pc += 1
        elif op == "STORE":
            a = pop()
            store[arg] = a
            pc += 1
        elif op == "JMP":
            check_target(arg)
            pc = arg
        elif op == "JZ":
            a = pop()
            if a == 0:
                check_target(arg)
                pc = arg
            else:
                pc += 1
        elif op == "CALL":
            check_target(arg)
            call_stack.append(pc + 1)
            pc = arg
        elif op == "RET":
            if not call_stack:
                raise StackUnderflow()
            pc = call_stack.pop()
        elif op == "HALT":
            return stack
        else:
            raise BadOpcode()

    return stack

sonnet-solo.text_table:
def format_table(rows: list[list], headers: list[str], *,
                  aligns: list[str] | None = None,
                  max_col_width: int = 20) -> str:
    if not headers:
        raise ValueError("headers must not be empty")

    n_cols = len(headers)

    for row in rows:
        if len(row) != n_cols:
            raise ValueError("row length does not match number of headers")

    if aligns is not None:
        if len(aligns) != n_cols:
            raise ValueError("aligns length does not match number of headers")
        for a in aligns:
            if a not in ("l", "r", "c"):
                raise ValueError("aligns must contain only 'l', 'r', or 'c'")
    else:
        aligns = ["l"] * n_cols

    if max_col_width < 1:
        raise ValueError("max_col_width must be >= 1")

    def to_text(value) -> str:
        if value is None:
            return ""
        return str(value)

    def raw_lines(text: str) -> list[str]:
        return text.split("\n")

    def max_line_len(text: str) -> int:
        lines = raw_lines(text)
        if not lines:
            return 0
        return max(len(line) for line in lines)

    def wrap_cell(text: str, width: int) -> list[str]:
        chunks: list[str] = []
        for line in raw_lines(text):
            if len(line) == 0:
                chunks.append("")
            else:
                for i in range(0, len(line), width):
                    chunks.append(line[i:i + width])
        return chunks

    def align_text(s: str, width: int, align: str) -> str:
        if align == "l":
            return s.ljust(width)
        if align == "r":
            return s.rjust(width)
        # center
        total_pad = width - len(s)
        if total_pad <= 0:
            return s
        left = total_pad // 2
        right = total_pad - left
        return (" " * left) + s + (" " * right)

    header_texts = [to_text(h) for h in headers]
    row_texts = [[to_text(v) for v in row] for row in rows]

    col_widths = []
    for j in range(n_cols):
        widest = max_line_len(header_texts[j])
        for row in row_texts:
            widest = max(widest, max_line_len(row[j]))
        col_widths.append(min(widest, max_col_width))

    def build_physical_row(texts: list[str]) -> list[list[str]]:
        col_chunks = [wrap_cell(texts[j], col_widths[j]) for j in range(n_cols)]
        height = max((len(c) for c in col_chunks), default=1)
        height = max(height, 1)
        for c in col_chunks:
            while len(c) < height:
                c.append("")
        return col_chunks

    def render_physical_row(col_chunks: list[list[str]]) -> list[str]:
        height = len(col_chunks[0]) if col_chunks else 0
        lines = []
        for line_idx in range(height):
            cells = []
            for j in range(n_cols):
                content = align_text(col_chunks[j][line_idx], col_widths[j], aligns[j])
                cells.append(" " + content + " ")
            lines.append("|" + "|".join(cells) + "|")
        return lines

    def border_line() -> str:
        return "+" + "+".join("-" * (w + 2) for w in col_widths) + "+"

    output_lines: list[str] = []
    output_lines.append(border_line())

    header_chunks = build_physical_row(header_texts)
    output_lines.extend(render_physical_row(header_chunks))

    output_lines.append(border_line())

    for row in row_texts:
        row_chunks = build_physical_row(row)
        output_lines.extend(render_physical_row(row_chunks))

    output_lines.append(border_line())

    return "\n".join(output_lines)

opus-solo.stack_vm:
"""A small stack-based virtual machine.

Public API:
    run(program, max_steps=10_000) -> list[int]
    VMError, StackUnderflow, BadJump, BadOpcode, StepLimitExceeded, VMZeroDivision
"""

__all__ = [
    "VMError",
    "StackUnderflow",
    "BadJump",
    "BadOpcode",
    "StepLimitExceeded",
    "VMZeroDivision",
    "run",
]


class VMError(Exception):
    """Base class for all VM errors."""


class StackUnderflow(VMError):
    """Popping or peeking an empty operand stack (or an empty call stack)."""


class BadJump(VMError):
    """Jump/call/return target out of range."""


class BadOpcode(VMError):
    """Unknown instruction name."""


class StepLimitExceeded(VMError):
    """Executed more than max_steps instructions."""


class VMZeroDivision(VMError):
    """DIV or MOD with a zero divisor."""


_NULLARY = frozenset(
    {
        "POP",
        "DUP",
        "SWAP",
        "ADD",
        "SUB",
        "MUL",
        "DIV",
        "MOD",
        "NEG",
        "EQ",
        "LT",
        "GT",
        "RET",
        "HALT",
    }
)

_UNARY = frozenset({"PUSH", "LOAD", "STORE", "JMP", "JZ", "CALL"})

_OPCODES = _NULLARY | _UNARY


def run(program, max_steps=10_000):
    """Execute `program` from index 0 and return the final operand stack."""
    stack = []
    store = {}
    calls = []
    pc = 0
    steps = 0

    n = len(program)

    def pop():
        if not stack:
            raise StackUnderflow("pop from empty operand stack")
        return stack.pop()

    def check_target(target):
        if not isinstance(target, int) or isinstance(target, bool):
            raise BadJump("jump target is not an integer: %r" % (target,))
        if target < 0 or target > n:
            raise BadJump("jump target out of range: %r" % (target,))
        return target

    while pc != n:
        if pc < 0 or pc > n:
            raise BadJump("program counter out of range: %r" % (pc,))

        if steps >= max_steps:
            raise StepLimitExceeded(
                "exceeded max_steps=%r" % (max_steps,)
            )
        steps += 1

        instr = program[pc]
        if not instr:
            raise BadOpcode("empty instruction at %d" % (pc,))
        op = instr[0]
        arg = instr[1] if len(instr) > 1 else None

        if op not in _OPCODES:
            raise BadOpcode("unknown opcode: %r" % (op,))

        if op == "PUSH":
            stack.append(arg)
            pc += 1
        elif op == "POP":
            pop()
            pc += 1
        elif op == "DUP":
            if not stack:
                raise StackUnderflow("DUP on empty operand stack")
            stack.append(stack[-1])
            pc += 1
        elif op == "SWAP":
            if len(stack) < 2:
                raise StackUnderflow("SWAP needs two operands")
            stack[-1], stack[-2] = stack[-2], stack[-1]
            pc += 1
        elif op == "ADD":
            b = pop()
            a = pop()
            stack.append(a + b)
            pc += 1
        elif op == "SUB":
            b = pop()
            a = pop()
            stack.append(a - b)
            pc += 1
        elif op == "MUL":
            b = pop()
            a = pop()
            stack.append(a * b)
            pc += 1
        elif op == "DIV":
            b = pop()
            a = pop()
            if b == 0:
                raise VMZeroDivision("DIV by zero")
            stack.append(a // b)
            pc += 1
        elif op == "MOD":
            b = pop()
            a = pop()
            if b == 0:
                raise VMZeroDivision("MOD by zero")
            stack.append(a % b)
            pc += 1
        elif op == "NEG":
            a = pop()
            stack.append(-a)
            pc += 1
        elif op == "EQ":
            b = pop()
            a = pop()
            stack.append(1 if a == b else 0)
            pc += 1
        elif op == "LT":
            b = pop()
            a = pop()
            stack.append(1 if a < b else 0)
            pc += 1
        elif op == "GT":
            b = pop()
            a = pop()
            stack.append(1 if a > b else 0)
            pc += 1
        elif op == "LOAD":
            stack.append(store.get(arg, 0))
            pc += 1
        elif op == "STORE":
            a = pop()
            store[arg] = a
            pc += 1
        elif op == "JMP":
            pc = check_target(arg)
        elif op == "JZ":
            a = pop()
            if a == 0:
                pc = check_target(arg)
            else:
                pc += 1
        elif op == "CALL":
            target = check_target(arg)
            calls.append(pc + 1)
            pc = target
        elif op == "RET":
            if not calls:
                raise StackUnderflow("RET with empty call stack")
            pc = check_target(calls.pop())
        elif op == "HALT":
            return stack

    return stack

opus-solo.text_table:
"""Render ASCII tables with exact, deterministic layout rules."""

__all__ = ["format_table"]

_VALID_ALIGNS = ("l", "r", "c")


def _cell_text(value):
    """Convert a raw cell value to its text form."""
    if value is None:
        return ""
    return str(value)


def _split_lines(text):
    """Split a cell's text on explicit newlines."""
    return text.split("\n")


def _hard_wrap(line, width):
    """Hard-break a single line into chunks of exactly `width` characters."""
    if width <= 0:
        return [""]
    if len(line) <= width:
        return [line]
    return [line[i:i + width] for i in range(0, len(line), width)]


def _wrap_cell(text, width):
    """Split on newlines, then hard-wrap each resulting line."""
    chunks = []
    for line in _split_lines(text):
        chunks.extend(_hard_wrap(line, width))
    return chunks or [""]


def _align(chunk, width, how):
    """Pad `chunk` to `width` according to alignment `how`."""
    pad = width - len(chunk)
    if pad <= 0:
        return chunk
    if how == "r":
        return " " * pad + chunk
    if how == "c":
        left = pad // 2
        right = pad - left
        return " " * left + chunk + " " * right
    return chunk + " " * pad


def _render_row(cells, widths, aligns):
    """Render one logical row (list of text cells) as physical lines."""
    wrapped = [_wrap_cell(text, widths[i]) for i, text in enumerate(cells)]
    height = max(len(chunks) for chunks in wrapped)
    lines = []
    for row_line in range(height):
        parts = []
        for col, chunks in enumerate(wrapped):
            chunk = chunks[row_line] if row_line < len(chunks) else ""
            parts.append(" " + _align(chunk, widths[col], aligns[col]) + " ")
        lines.append("|" + "|".join(parts) + "|")
    return lines


def _border(widths):
    return "+" + "+".join("-" * (w + 2) for w in widths) + "+"


def format_table(rows, headers, *, aligns=None, max_col_width=20):
    """Render `rows` as an ASCII table under `headers`.

    Cells are stringified (``None`` becomes ""), hard-wrapped to the column
    width, and padded with one space on each side. Column width is the larger
    of the header width and the widest cell line, capped at `max_col_width`.
    """
    if not headers:
        raise ValueError("headers must not be empty")

    ncols = len(headers)

    if not isinstance(max_col_width, int) or isinstance(max_col_width, bool):
        max_col_width = int(max_col_width)
    if max_col_width < 1:
        raise ValueError("max_col_width must be at least 1")

    if aligns is None:
        aligns = ["l"] * ncols
    else:
        aligns = list(aligns)
        if len(aligns) != ncols:
            raise ValueError("aligns must have one entry per column")
        for a in aligns:
            if a not in _VALID_ALIGNS:
                raise ValueError("aligns entries must be 'l', 'r' or 'c'")

    header_texts = [_cell_text(h) for h in headers]

    body = []
    for row in rows:
        row = list(row)
        if len(row) != ncols:
            raise ValueError("every row must have exactly len(headers) cells")
        body.append([_cell_text(c) for c in row])

    widths = []
    for col in range(ncols):
        widest = 0
        for line in _split_lines(header_texts[col]):
            widest = max(widest, len(line))
        for row in body:
            for line in _split_lines(row[col]):
                widest = max(widest, len(line))
        widths.append(min(widest, max_col_width))

    out = [_border(widths)]
    out.extend(_render_row(header_texts, widths, aligns))
    out.append(_border(widths))
    for row in body:
        out.extend(_render_row(row, widths, aligns))
    out.append(_border(widths))

    return "\n".join(out)
